nodes=[{'id':id,'label':label,'type':type,'aliases':aliases.split('|')} for id,label,type,aliases in noderaw]
links=[
('diabetes','type1','có thể'),('diabetes','type2','có thể'),('diabetes','gestational','có thể'),('prediabetes','type2','làm tăng nguy cơ'),('type1','immune','liên quan'),('immune','pancreas','tác động'),('pancreas','insulin','tiết ra'),('insulin','glucose','điều hòa'),('type1','insulin','cần điều trị'),('type2','resistance','liên quan'),('resistance','insulin','giảm hiệu quả'),('diabetes','glucose','tăng'),('diabetes','thirst','có triệu chứng'),('diabetes','urination','có triệu chứng'),('diabetes','fatigue','có triệu chứng'),('diabetes','vision','có triệu chứng'),('diabetes','a1c','được xét nghiệm bằng'),('diabetes','fasting','được xét nghiệm bằng'),('a1c','diagnosis','hỗ trợ'),('fasting','diagnosis','hỗ trợ'),('type2','family_history','yếu tố nguy cơ'),('type2','weight','yếu tố nguy cơ'),('exercise','prevention','hỗ trợ'),('food','prevention','hỗ trợ'),('weight','prevention','cần quản lý'),('prevention','type2','có thể giảm nguy cơ'),('diabetes','hypoglycemia','có thể gặp khi điều trị'),('hypoglycemia','rule15','cách xử trí phù hợp trường hợp'),('hypoglycemia','glucagon','có thể dùng khi nặng'),('hypoglycemia','emergency','có thể cần'),('type1','dka','nguy cơ'),('dka','emergency','đòi hỏi'),('diabetes','kidney','có biến chứng'),('diabetes','retinopathy','có biến chứng'),('diabetes','neuropathy','có biến chứng'),('neuropathy','foot','ảnh hưởng'),('diabetes','heart','có biến chứng'),('type2','metformin','có thể điều trị bằng'),('diabetes','monitoring','cần'),('monitoring','a1c','bao gồm'),('monitoring','kidney','bao gồm'),('monitoring','retinopathy','bao gồm'),('gestational','pregnancy','xuất hiện khi'),('gestational','type2','tăng nguy cơ sau sinh')]
edges=[]
for j,(src,dst,rel) in enumerate(links,1):
 supporting=[d['id'] for d in docs if src in d['entities'] and dst in d['entities']]
 if not supporting:
  supporting=[d['id'] for d in docs if src in d['entities']][:2]
 edges.append({'id':f'E{j:03}', 'source':src, 'target':dst, 'relation':rel, 'doc_ids':supporting})
for name,obj in [('documents.json',docs),('graph.json',{'nodes':nodes,'edges':edges})]:
 (ROOT/'data'/name).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
print('seed data',len(docs),'documents',len(nodes),'nodes',len(edges),'edges')
